fn yarra(arr: &Vec<char>) -> Vec<char> {
    // Produce a new vector; do not modify `arr`.
    // Iterator-based reversal avoids any usize underflow edge cases.
    let mut outarr = Vec::with_capacity(arr.len());
    outarr.extend(arr.iter().rev().copied());
    outarr
}

